// Parse and validate Perplexity response
const rawResponse = $('Message a model').first().json.content.parts[0].text;

// Extract JSON from response (handles markdown wrapping)
let jsonText = '';

if (rawResponse.choices && rawResponse.choices[0] && rawResponse.choices[0].message) {
  jsonText = rawResponse.choices[0].message.content;
} else if (typeof rawResponse === 'string') {
  jsonText = rawResponse;
} else {
  jsonText = JSON.stringify(rawResponse);
}

// Remove markdown code blocks if present
jsonText = jsonText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

// Try to extract array if wrapped in text
const arrayMatch = jsonText.match(/\[[\s\S]*\]/);
if (arrayMatch) {
  jsonText = arrayMatch[0];
}

let companies = [];
try {
  companies = JSON.parse(jsonText);
} catch (e) {
  console.error('Failed to parse JSON:', e);
  console.error('Raw text:', jsonText);
  return [];
}

// Validate and clean data
const validCompanies = companies
  .filter(company => {
    // Must have required fields
    if (!company.email || !company.company) return false;

    // Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(company.email)) return false;

    // Avoid generic emails
    const genericEmails = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
    const domain = company.email.split('@')[1];
    if (genericEmails.includes(domain)) return false;

    return true;
  })
  .map(company => ({
    company: company.company.trim(),
    email: company.email.toLowerCase().trim(),
    contact_name: company.contact_name || 'Hiring Team',
    website: company.website || '',
    source: company.source || 'Perplexity',
    validated: true
  }));

if (validCompanies.length === 0) {
  throw new Error('No valid companies found after validation');
}

console.log(`Validated ${validCompanies.length} companies`);

return validCompanies.map(company => ({ json: company }));

// Get existing emails from sheet with error handling
let existingEmails = new Set();

try {
  const existingData = $('Google Sheets - Check Existing').all();

  existingData.forEach(item => {
    // Handle different response formats
    const email = item.json.Email || item.json[0] || item.json.value;
    if (email && typeof email === 'string' && email.includes('@')) {
      existingEmails.add(email.toLowerCase().trim());
    }
  });

  console.log(`Found ${existingEmails.size} existing emails in sheet`);
} catch (error) {
  console.log('Warning: Could not read existing emails from sheet');
  console.log('Continuing without deduplication check');
  console.log('Error:', error.message);
  // Continue without deduplication if sheet read fails
}

// Get new companies from previous node
const newCompanies = $('Parse & Validate').all();

if (existingEmails.size === 0) {
  // No existing data or read failed - return all companies
  console.log('No existing data found - processing all companies');
  return newCompanies;
}

// Filter out duplicates
const uniqueCompanies = newCompanies.filter(item => {
  const email = item.json.email.toLowerCase().trim();
  return !existingEmails.has(email);
});

if (uniqueCompanies.length === 0) {
  console.log('No new companies found - all are duplicates');
  return [];
}

console.log(`Found ${uniqueCompanies.length} unique companies out of ${newCompanies.length} total`);

return uniqueCompanies;

// Format data for Google Sheets
const company = $('Loop Over Items').first().json;
const description = $input.first().json.content.parts[0].text;


// Format for Google Sheets
return [{
  json: {
    Email: company.email,
    Company: company.company,
    'Full Name': company.contact_name,
    Company_description: description,
    Website: company.website,
    Source: company.source || 'Perplexity',
    Date_Added: new Date().toISOString().split('T')[0]
  }
}];
